def max_non_overlapping(nums, target):
    n = len(nums)
    matches = []
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += nums[end]                                             # extend the subarray by one and recompute its sum directly
            if total == target:
                matches.append((start, end))

    def backtrack(idx, last_end):
        if idx == len(matches):
            return 0
        skip = backtrack(idx + 1, last_end)                                # option 1: don't use this match at all
        take = 0
        if matches[idx][0] > last_end:                                     # option 2: use this match, if it doesn't overlap the previous choice
            take = 1 + backtrack(idx + 1, matches[idx][1])
        return max(skip, take)

    return backtrack(0, -1)


if __name__ == "__main__":
    print(max_non_overlapping([1, 1, 1, 1, 1], 2))

