import java.util.*;

public class Main {
    int maxNonOverlapping(int[] nums, int target) {
        int n = nums.length;
        List<int[]> matches = new ArrayList<>();
        for (int start = 0; start < n; start++) {
            int total = 0;
            for (int end = start; end < n; end++) {
                total += nums[end];                                              // extend the subarray by one and recompute its sum directly
                if (total == target) matches.add(new int[]{start, end});
            }
        }
        return backtrack(matches, 0, -1);
    }

    int backtrack(List<int[]> matches, int idx, int lastEnd) {
        if (idx == matches.size()) return 0;
        int skip = backtrack(matches, idx + 1, lastEnd);                          // option 1: don't use this match at all
        int take = 0;
        if (matches.get(idx)[0] > lastEnd) {                                       // option 2: use this match, if it doesn't overlap the previous choice
            take = 1 + backtrack(matches, idx + 1, matches.get(idx)[1]);
        }
        return Math.max(skip, take);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxNonOverlapping(new int[]{1, 1, 1, 1, 1}, 2));
    }
}

