#include <bits/stdc++.h>
using namespace std;

int backtrack(vector<pair<int,int>>& matches, int idx, int lastEnd) {
    if (idx == (int)matches.size()) return 0;
    int skip = backtrack(matches, idx + 1, lastEnd);                            // option 1: don't use this match at all
    int take = 0;
    if (matches[idx].first > lastEnd) {                                          // option 2: use this match, if it doesn't overlap the previous choice
        take = 1 + backtrack(matches, idx + 1, matches[idx].second);
    }
    return max(skip, take);
}

int maxNonOverlapping(vector<int>& nums, int target) {
    int n = (int)nums.size();
    vector<pair<int,int>> matches;
    for (int start = 0; start < n; start++) {
        int total = 0;
        for (int end = start; end < n; end++) {
            total += nums[end];                                                  // extend the subarray by one and recompute its sum directly
            if (total == target) matches.push_back({start, end});
        }
    }
    return backtrack(matches, 0, -1);
}

