import java.util.*;

public class Main {
    int maxNonOverlapping(int[] nums, int target) {
        Set<Integer> seen = new HashSet<>();
        seen.add(0);                                                              // prefix sums seen SINCE the last cut (0 represents "no elements yet")
        int prefix = 0;
        int count = 0;
        for (int x : nums) {
            prefix += x;
            if (seen.contains(prefix - target)) {                                   // a subarray summing to target ends exactly here
                count++;                                                             // greedily take it immediately, the earliest possible ending point
                seen = new HashSet<>();                                              // reset tracking completely; nothing before this point can be reused
                seen.add(0);
                prefix = 0;
            } else {
                seen.add(prefix);
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxNonOverlapping(new int[]{1, 1, 1, 1, 1}, 2));
    }
}

